def pipeline_cycles(inputs):
    graph = {}                                   # dataset -> the datasets it reads
    for ds, ins in inputs.items():
        graph.setdefault(ds, []).extend(ins)
        for i in ins:
            graph.setdefault(i, [])
    self_loop = {ds for ds, ins in inputs.items() if ds in ins}
    index, low = {}, {}
    on_stack, stack, groups = set(), [], []
    counter = 0
    for root in graph:                           # iterative Tarjan: no recursion limit
        if root in index:
            continue
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        on_stack.add(root)
        work = [(root, iter(graph[root]))]
        while work:
            node, it = work[-1]
            descended = False
            for nxt in it:
                if nxt not in index:
                    index[nxt] = low[nxt] = counter
                    counter += 1
                    stack.append(nxt)
                    on_stack.add(nxt)
                    work.append((nxt, iter(graph[nxt])))
                    descended = True
                    break
                if nxt in on_stack and index[nxt] < low[node]:
                    low[node] = index[nxt]
            if descended:
                continue
            work.pop()
            if work:
                parent = work[-1][0]
                if low[node] < low[parent]:
                    low[parent] = low[node]
            if low[node] == index[node]:         # node is the root of a component
                comp = []
                while True:
                    w = stack.pop()
                    on_stack.discard(w)
                    comp.append(w)
                    if w == node:
                        break
                if len(comp) > 1 or node in self_loop:
                    groups.append(sorted(comp))
    groups.sort()
    return groups

